import {Mode} from './mode-base.js';
import {THREE,ball,ring,moveActor,distance} from './world.js';

// The neighbourhood rule supplied by the player: hit somebody, then catch the
// rebound before it touches the floor. Otherwise retrieve the ball and try again.
export class Stay extends Mode {
 constructor(ctx){
  super(ctx);this.world.setCamera([0,17,17,0,0,0]);
  this.players=[];for(let i=0;i<8;i++){const a=i*Math.PI/4;this.players.push(this.player(Math.sin(a)*6,Math.cos(a)*6,[this.settings.color,0x357e7c,0xc49e4e,0x416e82,0xa65640,0x687a48,0x9d7957,0x6f6690][i]));}
  this.you=this.players[0];this.throwerIndex=0;this.thrower=this.you;this.targetIndex=4;this.b=ball(this.root,.13);this.v=new THREE.Vector3();this.phase='held';this.hitIndex=null;this.catchWindow=0;this.kickCooldown=0;this.roleTime=0;this.transfers=Array(8).fill(0);this.marker=ring(.5,0xf2bd51,0,0,this.root,.025);this.targetMarker=ring(.48,0xd88853,0,0,this.root,.018);this.youMarker=ring(.38,0xf3e6c7,0,0,this.root,.016);this.labels=this.players.map((p,i)=>this.text(i?String(i+1):'YOU',p.position.x,2.45,p.position.z,'#f5e5bc',.22));
  this.controls();
  this.note('You have the ball. Aim at a player, throw, then catch the rebound before it lands. E changes target.');this.attachBall();
 }
 controls(){const key=this.throwerIndex+':'+this.phase;if(this.controlKey===key)return;this.controlKey=key;const mine=this.throwerIndex===0,held=this.phase==='held',loose=this.phase==='loose';this.setActions([{id:'ball',label:held?'Throw':'Catch',key:'Space',disabled:!mine||loose},{id:'play',label:held?'Target':'Kick away',key:'E',disabled:!(mine&&held||!mine&&loose)},{id:'sprint',label:'Sprint',key:'Shift',hold:true}]);}
 attachBall(){this.b.position.copy(this.thrower.position);this.b.position.y=1.15;this.b.position.z+=.18;}
 chooseTarget(){const choices=this.players.map((p,i)=>({p,i})).filter(q=>q.i!==this.throwerIndex);choices.sort((a,b)=>distance(a.p,this.thrower)-distance(b.p,this.thrower));return choices[0].i;}
 launch(){if(this.phase!=='held')return;const p=this.players[this.targetIndex];this.attachBall();const duration=THREE.MathUtils.clamp(distance(p,this.thrower)/13,.25,1.2);const lead=p.userData.stayVelocity||{x:0,z:0};this.v.set((p.position.x+lead.x*duration*.6-this.b.position.x)/duration,(1.05-this.b.position.y+4*duration*duration)/duration,(p.position.z+lead.z*duration*.6-this.b.position.z)/duration);this.phase='flight';this.flightTime=0;this.hitIndex=null;this.catchWindow=0;this.thrower.userData.pose='point';this.ui.sound('throw');this.note(this.throwerIndex===0?'Follow the ball. If it hits, move under the rebound and press Catch.':'Dodge the throw. If it lands loose, kick it away from the thrower.');}
 action(id){if(id==='ball'){if(this.throwerIndex!==0)return this.note('Keep clear of the throw. E kicks a loose ball away.');if(this.phase==='held')this.launch();else if(this.phase==='rebound'||this.phase==='flight'){this.catchWindow=.6;this.you.userData.pose='reach';}else this.note('Run to the loose ball to collect it.');}else if(id==='play'){if(this.phase==='held'&&this.throwerIndex===0){do{this.targetIndex=(this.targetIndex+1)%this.players.length;}while(this.targetIndex===0);}else if(this.phase==='loose'&&this.throwerIndex!==0)this.kickLoose(0);}}
 hit({point}){if(this.phase==='held'&&this.throwerIndex===0){let best=Infinity;this.players.forEach((p,i)=>{const d=distance(p,point);if(i!==0&&d<best){best=d;this.targetIndex=i;}});}else this.input.target=point;}
 rebound(index){if(this.phase!=='flight')return;this.hitIndex=index;this.phase='rebound';const duration=THREE.MathUtils.clamp(distance(this.b,this.thrower)/10,.35,1);this.v.set((this.thrower.position.x-this.b.position.x)/duration,(1.1-this.b.position.y+4*duration*duration)/duration,(this.thrower.position.z-this.b.position.z)/duration);this.ui.sound('ballHit');this.note(this.throwerIndex===0?'Hit! Catch the rebound before it touches the ground.':'Hit — the role changes only if the thrower catches the rebound.');}
 catchRebound(){if(this.phase!=='rebound'||this.hitIndex===null)return false;const old=this.throwerIndex,next=this.hitIndex;this.transfers[old]++;this.score=this.transfers[0];this.throwerIndex=next;this.thrower=this.players[next];this.hitIndex=null;this.phase='held';this.roleTime=0;this.catchWindow=0;this.v.set(0,0,0);this.targetIndex=this.chooseTarget();this.attachBall();this.ui.sound('catch');this.note(next===0?'They hit you and caught it. Your turn to throw, hit and catch.':'Caught! The hit player now becomes the thrower. Keep the loose ball away from them.');return true;}
 loose(){this.phase='loose';this.hitIndex=null;this.catchWindow=0;this.note(this.throwerIndex===0?'No catch. Chase and collect the ball — everyone else can kick it away.':'Loose ball! Reach it and press E to kick it away from the thrower.');}
 kickLoose(index){if(this.phase!=='loose'||index===this.throwerIndex||this.kickCooldown>0||distance(this.players[index],this.b)>1.1||this.b.position.y>.65)return false;const dir=this.b.position.clone().sub(this.thrower.position);dir.y=0;if(dir.length()<.1)dir.set(1,0,0);dir.normalize();this.v.copy(dir.multiplyScalar(8.5));this.v.y=1.4;this.kickCooldown=.7;this.players[index].userData.kick=.38;this.ui.sound('kick');return true;}
 update(dt,t){
  this.controls();this.roleTime+=dt;this.catchWindow=Math.max(0,this.catchWindow-dt);this.kickCooldown=Math.max(0,this.kickCooldown-dt);this.move(this.you,dt,this.input.sprint?7:5,11);this.you.position.z=THREE.MathUtils.clamp(this.you.position.z,-9,9);
  this.players.forEach((p,i)=>{if(i===0)return;let target,speed=2.2;if(i===this.throwerIndex){if(this.phase==='held'){target=this.players[this.targetIndex].position;speed=distance(p,target)>7?2.8:0;}else{target=this.b.position;speed=this.phase==='loose'?4.8:4.2;}}else if(this.phase==='loose'){target=this.b.position;speed=3.4;}else{const a=t*.13+i*Math.PI/4;target={x:Math.sin(a)*7,z:Math.cos(a)*7};if((this.phase==='flight'||this.phase==='held')&&distance(p,this.b)<1.5){const dx=p.position.x-this.thrower.position.x,dz=p.position.z-this.thrower.position.z;target={x:p.position.x+dz,z:p.position.z-dx};speed=2.6;}}const old=p.position.clone();p.userData.run=moveActor(p,target,speed,dt);p.userData.stayVelocity=p.position.clone().sub(old).divideScalar(Math.max(dt,.001));p.position.x=THREE.MathUtils.clamp(p.position.x,-11,11);p.position.z=THREE.MathUtils.clamp(p.position.z,-9,9);if(this.phase==='loose'&&i!==this.throwerIndex)this.kickLoose(i);});
  this.youMarker.position.set(this.you.position.x,.03,this.you.position.z);this.labels.forEach((l,i)=>l.position.set(this.players[i].position.x,2.45,this.players[i].position.z));
  this.marker.position.set(this.thrower.position.x,.025,this.thrower.position.z);this.targetMarker.visible=this.phase==='held'&&this.throwerIndex===0;this.targetMarker.position.set(this.players[this.targetIndex].position.x,.02,this.players[this.targetIndex].position.z);
  this.status(this.throwerIndex===0?'YOU HAVE THE THROW':`PLAYER ${this.throwerIndex+1} HAS THE THROW`,`${this.players.length} PLAYERS · ${this.transfers.reduce((a,b)=>a+b,0)} ROLE CHANGES · ${this.phase==='rebound'?'CATCH BEFORE IT LANDS':this.phase==='loose'?'CHASE THE BALL':'HIT + CATCH TO SWITCH'}`);
  if(this.phase==='held'){this.attachBall();if(this.throwerIndex!==0&&this.roleTime>2){this.targetIndex=this.chooseTarget();this.launch();}return;}
  this.flightTime=(this.flightTime||0)+dt;this.b.position.addScaledVector(this.v,dt);this.v.y-=8*dt;
  for(const axis of ['x','z']){const bound=axis==='x'?11.5:9.5;if(Math.abs(this.b.position[axis])>bound){this.b.position[axis]=Math.sign(this.b.position[axis])*bound;this.v[axis]*=-.65;if(this.phase!=='loose')this.loose();this.ui.sound('bounce');}}
  if(this.phase==='flight'){const hit=this.players.findIndex((p,i)=>i!==this.throwerIndex&&distance(p,this.b)<.55&&this.b.position.y>.22&&this.b.position.y<1.7);if(hit>=0)this.rebound(hit);}
  if(this.phase==='rebound'&&distance(this.b,this.thrower)<.9&&this.b.position.y>.3&&this.b.position.y<1.8&&(this.throwerIndex!==0||this.catchWindow>0)){this.catchRebound();return;}
  if(this.b.position.y<=.13){this.b.position.y=.13;if(this.phase!=='loose')this.loose();if(Math.abs(this.v.y)>.5)this.ui.sound('bounce');this.v.y=Math.abs(this.v.y)>.5?Math.abs(this.v.y)*.35:0;this.v.x*=.93;this.v.z*=.93;}
  if(this.phase==='loose'){this.v.x*=Math.exp(-dt*.35);this.v.z*=Math.exp(-dt*.35);if(distance(this.b,this.thrower)<.8&&this.b.position.y<.65){this.phase='held';this.v.set(0,0,0);this.roleTime=0;this.targetIndex=this.chooseTarget();this.attachBall();this.ui.sound('catch');this.note(this.throwerIndex===0?'Collected. Aim, hit a player, and catch the rebound.':'The thrower collected it. Stay alert for the next throw.');}}
 }
}
